// Group by level for easy rendering
export const GRAMMAR_LEVELS = ['TOPIK 1급', 'TOPIK 2급', 'TOPIK 3급', 'TOPIK 4급', 'TOPIK 5급', 'TOPIK 6급'] as const;
export type GrammarLevel = typeof GRAMMAR_LEVELS[number];

export function getGrammarByLevel(level: GrammarLevel): GrammarGuideItem[] {
  return grammarGuide.filter(g => g.topikLevel === level);
}
